/// <summary>
/// Data contract class for service <c>METSendPEPricingRequest</c>
/// </summary>
[DataContractAttribute]
public class METSendPEPricingRequest
{
    DataAreaId  dataAreaId;
    private     METSendPricingHeaderContract sendPricingHeaderClass;
    private     List sendPEPricingLineArray;



}

Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// To get the sendPricingHeaderClass
/// </summary>
/// <param name = "_sendPricingHeaderClass">Send Pricing Header</param>
/// <returns>header Pricing class</returns>
[DataMember("METSendPricingHeaderContract")]
public METSendPricingHeaderContract parmSendPricingHeaderContract(METSendPricingHeaderContract _sendPricingHeaderClass = sendPricingHeaderClass)
{
    if (!prmIsDefault(_sendPricingHeaderClass))
    {
        sendPricingHeaderClass = _sendPricingHeaderClass;
    }
    return sendPricingHeaderClass;
}

/// <summary>
/// send PE pricing line
/// </summary>
/// <param name = "_sendPEPricingLineClassArray">PEpricingLine</param>
/// <returns>returns pricing line class</returns>
[DataMemberAttribute("METSendPricingLineContract"),
DataCollection(Types::Class, classStr(METSendPricingLineContract)),
AifCollectionTypeAttribute('_sendPEPricingLineClassArray', Types::Class, classStr(METSendPricingLineContract)),
AifCollectionTypeAttribute('return', Types::Class, classStr(METSendPricingLineContract))]
public List parmsendPEPricingLineClassArray(List _sendPEPricingLineClassArray = sendPEPricingLineArray)
{
    if (!prmIsDefault(_sendPEPricingLineClassArray))
    {
        sendPEPricingLineArray = _sendPEPricingLineClassArray;
    }

    return sendPEPricingLineArray;
}
